import { useState } from "react";
import { HiMenu, HiX } from "react-icons/hi";
import PacesLogo from "../Images/Paces+White_logo.png";
import { HashLink as Link } from "react-router-hash-link";
import { useLocation } from "react-router-dom";

const Nav = () => {
  const { hash } = useLocation();
  const [toggleMenu, setToggleMenu] = useState(false);
  const isActive = (iHash) => hash === iHash;

  const menuItems = [
    { label: "Home", hash: "#home" },
    { label: "About", hash: "#about" },
    { label: "Gallery", hash: "#gallery" },
  ];

  return (
    <header className="sticky top-0 z-50 border-b border-white/10 bg-black/40 backdrop-blur-xl">
      <div className="mx-auto flex max-w-7xl items-center justify-between px-4 py-4 sm:px-6 lg:px-8">
        <Link
          smooth
          to="#home"
          className="flex items-center gap-3"
          aria-label="Go to home section"
        >
          <img
            src={PacesLogo}
            alt="Paces Worldwide logo"
            className="h-10 w-auto"
          />
        </Link>

        <button
          type="button"
          className="rounded-full border border-white/20 p-2 text-white transition hover:bg-white/10 md:hidden"
          onClick={() => setToggleMenu((value) => !value)}
          aria-expanded={toggleMenu}
          aria-controls="site-navigation"
          aria-label="Toggle navigation"
        >
          {toggleMenu ? <HiX size={22} /> : <HiMenu size={22} />}
        </button>

        <nav
          id="site-navigation"
          className="hidden items-center gap-2 md:flex"
          aria-label="Primary navigation"
        >
          {menuItems.map((item) => (
            <Link
              key={item.hash}
              smooth
              to={item.hash}
              className={`rounded-full px-4 py-2 text-sm font-medium transition ${
                isActive(item.hash)
                  ? "bg-white text-slate-900"
                  : "text-slate-200 hover:bg-white/10"
              }`}
            >
              {item.label}
            </Link>
          ))}
          <Link
            smooth
            to="#contact"
            className={`rounded-full px-4 py-2 text-sm font-semibold transition ${
              isActive("#contact")
                ? "bg-amber-400 text-slate-950"
                : "bg-white/10 text-white hover:bg-white/20"
            }`}
          >
            Book a Stay
          </Link>
        </nav>
      </div>

      {toggleMenu && (
        <div className="border-t border-white/10 bg-black/70 px-4 py-4 backdrop-blur md:hidden">
          <nav className="flex flex-col gap-2" aria-label="Mobile navigation">
            {menuItems.map((item) => (
              <Link
                key={item.hash}
                smooth
                to={item.hash}
                className={`rounded-2xl px-4 py-3 text-sm font-medium ${
                  isActive(item.hash)
                    ? "bg-white text-slate-900"
                    : "bg-white/10 text-white"
                }`}
                onClick={() => setToggleMenu(false)}
              >
                {item.label}
              </Link>
            ))}
            <Link
              smooth
              to="#contact"
              className={`rounded-2xl px-4 py-3 text-sm font-semibold ${
                isActive("#contact")
                  ? "bg-amber-400 text-slate-950"
                  : "bg-white/10 text-white"
              }`}
              onClick={() => setToggleMenu(false)}
            >
              Book a Stay
            </Link>
          </nav>
        </div>
      )}
    </header>
  );
};

export default Nav;
